import XCTest

final class ElementUITests: XCTestCase {
    func testOpenSessions() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        let pred = NSPredicate(format: "label CONTAINS[c] 'session' OR label CONTAINS[c] 'device'")
        for _ in 0..<10 {
            let hits = app.descendants(matching: .any).matching(pred).allElementsBoundByIndex
            for h in hits {
                print("HIT>>> type=\(h.elementType.rawValue) label=\(h.label) hittable=\(h.isHittable) frame=\(h.frame)")
            }
            if let hit = hits.first(where: { $0.isHittable && $0.label.lowercased().contains("session") }) {
                hit.tap()
                break
            }
            app.swipeDown()
            sleep(1)
        }
        sleep(2)
    }
}
EOF
